{
  "tool": "search_pull_requests",
  "description": "Search for pull requests in GitHub repositories using issues search syntax already scoped to is:pr",
  "inputSchema": {
    "type": "object",
    "properties": {
      "fields": {
        "type": "array",
        "items": {
          "type": "string",
          "enum": [
            "number",
            "title",
            "body",
            "state",
            "state_reason",
            "draft",
            "locked",
            "html_url",
            "user",
            "author_association",
            "labels",
            "assignee",
            "assignees",
            "milestone",
            "comments",
            "reactions",
            "created_at",
            "updated_at",
            "closed_at",
            "closed_by",
            "pull_request",
            "repository_url"
          ]
        },
        "description": "Subset of fields to return for each pull request result. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'body', 'reactions', and 'labels' in particular drops the largest per-result data."
      },
      "order": {
        "type": "string",
        "description": "Sort order",
        "enum": [
          "asc",
          "desc"
        ]
      },
      "owner": {
        "type": "string",
        "description": "Optional repository owner. If provided with repo, only pull requests for this repository are listed.",
        "x-mcp-header": "owner"
      },
      "page": {
        "type": "number",
        "description": "Page number for pagination (min 1)",
        "minimum": 1
      },
      "perPage": {
        "type": "number",
        "description": "Results per page for pagination (min 1, max 100)",
        "minimum": 1,
        "maximum": 100
      },
      "query": {
        "type": "string",
        "description": "Search query using GitHub pull request search syntax"
      },
      "repo": {
        "type": "string",
        "description": "Optional repository name. If provided with owner, only pull requests for this repository are listed.",
        "x-mcp-header": "repo"
      },
      "sort": {
        "type": "string",
        "description": "Sort field by number of matches of categories, defaults to best match",
        "enum": [
          "comments",
          "reactions",
          "reactions-+1",
          "reactions--1",
          "reactions-smile",
          "reactions-thinking_face",
          "reactions-heart",
          "reactions-tada",
          "interactions",
          "created",
          "updated"
        ]
      }
    },
    "required": [
      "query"
    ]
  }
}

{
  "tool": "list-cloud-agents",
  "description": "List cloud agents accessible to the current run's principal in this run's environment (or, for a run without a saved environment, agents on the same repository), ordered by creation time (newest first). Users and service accounts see their own runs. Team admins can additionally browse teammates' runs only when enabled in team MCP settings. Returns basic run metadata plus URLs. Filters: source, lifecycle status, setup status, recency/creation windows, archived, self-hosted, code changes, and pull-request creation. Paging: limit (default 50, max 200) + offset; the response includes returned, offset, limit, hasMore, nextOffset when more accessible agents were found, and totalMatched only when the accessible scan is complete. With many cloud agents, narrow with filters before paging through everything.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "sources": {
        "type": "array",
        "items": {
          "type": "string",
          "enum": [
            "desktop",
            "web",
            "mobile",
            "slack",
            "linear",
            "scm",
            "cli",
            "sand",
            "setup",
            "sdk",
            "automations",
            "api",
            "bugbot_autofix",
            "qabot_frontend",
            "local",
            "internal"
          ]
        },
        "maxItems": 50,
        "description": "Filter by agent source category, matching the source field returned in results. One or more of: desktop, web, mobile, slack, linear, scm, cli, sand, setup, sdk, automations, api, bugbot_autofix, qabot_frontend, local, internal."
      },
      "statuses": {
        "type": "array",
        "items": {
          "type": "string",
          "enum": [
            "UNSPECIFIED",
            "NOT_YET_STARTED",
            "RUNNING",
            "IDLE",
            "ERROR",
            "ARCHIVED",
            "EXPIRED",
            "WAITING_FOR_BACKGROUND_WORK"
          ]
        },
        "maxItems": 50,
        "description": "Filter by lifecycle status(es), matching the status field returned in results."
      },
      "setupStatus": {
        "anyOf": [
          {
            "type": "string",
            "enum": [
              "INSTALL_STARTED",
              "INSTALL_SUCCEEDED",
              "INSTALL_FAILED"
            ]
          },
          {
            "type": "null"
          }
        ],
        "description": "Filter by user install setup status. INSTALL_FAILED indicates a confirmed failure, INSTALL_SUCCEEDED indicates a confirmed success, and INSTALL_STARTED indicates that setup started without a recorded outcome. null means no status was recorded and does not establish success or failure. Omit this field to apply no setup-status filter."
      },
      "includeArchived": {
        "type": "boolean",
        "description": "Include archived/killed agents. Defaults to false."
      },
      "activeSince": {
        "type": "string",
        "description": "Only include agents with activity at or after this ISO-8601 UTC instant. Omitted by default."
      },
      "createdAfter": {
        "type": "string",
        "description": "Only include agents created at or after this ISO-8601 UTC instant."
      },
      "createdBefore": {
        "type": "string",
        "description": "Only include agents created at or before this ISO-8601 UTC instant."
      },
      "isSelfHostedWorker": {
        "type": "boolean",
        "description": "Filter by where the agent runs: true for self-hosted private-worker agents, false for managed public-cloud agents, omit for both."
      },
      "didMakeCodeChanges": {
        "type": "boolean",
        "description": "Filter by whether the agent made code changes (committed or not): true for agents with a recorded non-zero diff (files/lines changed), false for agents with no recorded changes, omit for both."
      },
      "didCreatePullRequest": {
        "type": "boolean",
        "description": "Filter by whether the agent created a pull request: true for agents with a PR, false for agents without one, omit for both."
      },
      "limit": {
        "type": "integer",
        "minimum": 1,
        "maximum": 200,
        "description": "Max number of agents to return (default 50, max 200)."
      },
      "offset": {
        "type": "integer",
        "minimum": 0,
        "description": "Number of matched accessible agents to skip before this page. Use the nextOffset from a previous response to page. Note: not a stable cursor — results are re-fetched and re-sorted each call, so offsets can shift if agents change between calls."
      }
    },
    "additionalProperties": false,
    "$schema": "http://json-schema.org/draft-07/schema#"
  }
}

{
  "tool": "batch-fetch-details",
  "description": "Fetch details for a batch of specified accessible cloud agents by bcIds. Users and service accounts can fetch their own runs. Team admins can additionally fetch teammates' runs only when enabled in team MCP settings. When matching agents are found, writes basic run info to index.json under a unique /tmp/cursor/cloud-agent-transcripts/<datetime-id>/ run directory, and can optionally write per-agent diff-metadata.json, setup-logs.txt, start-logs.txt, environment-info.json, events.json, and transcript.json files. Set includeEvents to include each run's dashboard events. First-class Task results include cloudAgentBcId, which can be passed to another batch-fetch-details call. Returns the run directory and written paths; transcripts can be very large, so read them via subagents, never directly.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "bcIds": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "minItems": 1,
        "maxItems": 50,
        "description": "Agent ids to fetch as a batch (max 50). Each id is access-checked and constrained to this run's environment (or, when this run has no saved environment, to agents on the same repository)."
      },
      "includeDiffMetadata": {
        "type": "boolean",
        "description": "Also write each agent's PR link/status and change counts to diff-metadata.json. Defaults to false."
      },
      "includeSetupLogs": {
        "type": "boolean",
        "description": "Also write each agent's pod setup and image-build logs to setup-logs.txt. Defaults to false."
      },
      "includeStartLogs": {
        "type": "boolean",
        "description": "Also write each agent's start-command stdout/stderr/exit lines to start-logs.txt (filtered from the same Redis setup stream as includeSetupLogs; includes system starts like exec-daemon interleaved with the user start script). Defaults to false."
      },
      "includeEnvironment": {
        "type": "boolean",
        "description": "Also write each agent's environment identity/config and egress policy to environment-info.json. Defaults to false."
      },
      "includeEvents": {
        "type": "boolean",
        "description": "Also write each agent's dashboard events to events.json. Defaults to false."
      },
      "includeTranscripts": {
        "type": "boolean",
        "description": "Also write each requested agent's full conversation to <bcId>/transcript.json. First-class Task tool results include cloudAgentBcId, which can be passed to a subsequent batch-fetch-details call. Defaults to false."
      }
    },
    "required": [
      "bcIds"
    ],
    "additionalProperties": false,
    "$schema": "http://json-schema.org/draft-07/schema#"
  }
}
